using System;using System.IO;using System.Net;using System.Net.Sockets;using System.Text;using System.Threading;using System.Diagnostics;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Windows.Forms;
class CurveDrive {
 static JavaScriptSerializer Json{get{return new JavaScriptSerializer{MaxJsonLength=4194304};}}
 static string Root=AppDomain.CurrentDomain.BaseDirectory,DataDir,Token=Guid.NewGuid().ToString("N");static int Port;static DateTime LastSeen=DateTime.UtcNow;static readonly object Gate=new object();static Mutex Disk;
 static string Project{get{return Path.Combine(DataDir,"Project.json");}}static string Backup{get{return Path.Combine(DataDir,"Project.previous.json");}}
 [STAThread]static int Main(string[] args){try{
  DataDir=Environment.GetEnvironmentVariable("CURVEDRIVE_FIELD_DATA");if(String.IsNullOrEmpty(DataDir))DataDir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CurveDriveField");Directory.CreateDirectory(DataDir);
  string mutexName="Local\\CurveDriveFieldSave_"+BitConverter.ToString(System.Security.Cryptography.SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(DataDir.ToUpperInvariant()))).Replace("-","").Substring(0,24);Disk=new Mutex(false,mutexName);
  if(!File.Exists(Path.Combine(Root,"dist","index.html")))throw new IOException("dist フォルダーが見つかりません。ZIPをすべて展開してください。");
  var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();Port=((IPEndPoint)listener.LocalEndpoint).Port;string url="http://127.0.0.1:"+Port+"/?nativeToken="+Token;
  File.WriteAllText(Path.Combine(DataDir,"runtime-"+Process.GetCurrentProcess().Id+".json"),Json.Serialize(new{url=url,pid=Process.GetCurrentProcess().Id}),new UTF8Encoding(false));
  if(Array.IndexOf(args,"--server-only")<0)Open(url);
  while(DateTime.UtcNow-LastSeen<TimeSpan.FromMinutes(10)){if(!listener.Pending()){Thread.Sleep(100);continue;}var client=listener.AcceptTcpClient();ThreadPool.QueueUserWorkItem(delegate{Serve(client);});}listener.Stop();return 0;
 }catch(Exception e){if(Array.IndexOf(args,"--server-only")<0)MessageBox.Show(e.Message,"カーブ推進 現場アプリ");return 1;}}
 static void Open(string url){foreach(string baseDir in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles)}){string edge=Path.Combine(baseDir,"Microsoft","Edge","Application","msedge.exe");if(File.Exists(edge)){Process.Start(new ProcessStartInfo(edge,"--app=\""+url+"\""){UseShellExecute=false});return;}}Process.Start(url);}
 static Dictionary<string,object> Map(object v){var d=v as Dictionary<string,object>;if(d==null)throw new InvalidDataException("保存形式が不正です");return d;}
 static Dictionary<string,object> Record(string text){var r=Map(Json.DeserializeObject(text));var d=Map(r["data"]);var basics=Map(d["basics"]);foreach(string k in new[]{"site","x0","y0","heading","pitch","z0","grade"})if(!basics.ContainsKey(k)||!(basics[k] is string))throw new InvalidDataException("基本情報が不正です");if(!(d["segs"] is System.Collections.IList)||((System.Collections.IList)d["segs"]).Count>1000||!(d["meas"] is System.Collections.IList)||((System.Collections.IList)d["meas"]).Count>20000)throw new InvalidDataException("入力形式が不正です");if(Convert.ToInt64(r["savedAt"])<0)throw new InvalidDataException("保存時刻が不正です");return r;}
 static string Load(){foreach(string p in new[]{Project,Backup})if(File.Exists(p)){try{string raw=File.ReadAllText(p,Encoding.UTF8);Record(raw);return raw;}catch{}}if(File.Exists(Project)||File.Exists(Backup))throw new IOException("保存データを読めません。バックアップを確認してください。");return "null";}
 static void Save(string body){var incoming=Record(body);bool acquired=false;try{try{acquired=Disk.WaitOne(4000);}catch(AbandonedMutexException){acquired=true;}if(!acquired)throw new IOException("保存待ちです");string old=Load();if(old!="null"&&Convert.ToInt64(Record(old)["savedAt"])>Convert.ToInt64(incoming["savedAt"]))throw new InvalidOperationException("新しい入力がすでに保存されています");string tmp=Path.Combine(DataDir,Guid.NewGuid().ToString("N")+".tmp");try{File.WriteAllText(tmp,body,new UTF8Encoding(false));if(File.Exists(Project))File.Replace(tmp,Project,Backup);else File.Move(tmp,Project);}finally{if(File.Exists(tmp))File.Delete(tmp);}}finally{if(acquired)Disk.ReleaseMutex();}}
 static void Send(NetworkStream stream,int status,byte[] data,string type){string text="HTTP/1.1 "+status+" "+(status==200?"OK":"Error")+"\r\nContent-Type: "+type+"\r\nContent-Length: "+data.Length+"\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nReferrer-Policy: no-referrer\r\n\r\n";byte[] h=Encoding.ASCII.GetBytes(text);stream.Write(h,0,h.Length);stream.Write(data,0,data.Length);}
 static void Reply(NetworkStream stream,int code,object data){Send(stream,code,Encoding.UTF8.GetBytes(Json.Serialize(data)),"application/json; charset=utf-8");}
 static void Serve(TcpClient client){using(client){client.ReceiveTimeout=5000;client.SendTimeout=5000;var stream=client.GetStream();try{
  var header=new List<byte>();int last=0;while(header.Count<16384){int b=stream.ReadByte();if(b<0)return;header.Add((byte)b);last=(last<<8)|b;if(last==0x0d0a0d0a)break;}if(last!=0x0d0a0d0a){Reply(stream,400,new{error="header"});return;}
  string[] lines=Encoding.ASCII.GetString(header.ToArray()).Split(new[]{"\r\n"},StringSplitOptions.None);string[] request=lines[0].Split(' ');if(request.Length!=3){Reply(stream,400,new{error="request"});return;}var headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in lines){int n=line.IndexOf(':');if(n>0)headers[line.Substring(0,n)]=line.Substring(n+1).Trim();}
  string host,origin="http://127.0.0.1:"+Port;if(!headers.TryGetValue("Host",out host)||host!="127.0.0.1:"+Port){Reply(stream,403,new{error="host"});return;}
  var uri=new Uri(origin+request[1]);string path=uri.AbsolutePath;LastSeen=DateTime.UtcNow;
  if(path.StartsWith("/api/",StringComparison.Ordinal)){
   string token;headers.TryGetValue("X-App-Token",out token);if(token==null)token=System.Web.HttpUtility.ParseQueryString(uri.Query)["token"];if(token!=Token){Reply(stream,403,new{error="token"});return;}
   if(request[0]=="GET"&&path=="/api/ping"){Reply(stream,200,new{ok=true});return;}
   if(request[0]=="GET"&&path=="/api/project"){string saved;lock(Gate)saved=Load();Send(stream,200,Encoding.UTF8.GetBytes(saved),"application/json; charset=utf-8");return;}
   if(request[0]=="POST"&&path=="/api/project"){
    string from;if(!headers.TryGetValue("Origin",out from)||from!=origin){Reply(stream,403,new{error="origin"});return;}
    string len;int length;if(!headers.TryGetValue("Content-Length",out len)||!Int32.TryParse(len,out length)||length<1||length>4194304){Reply(stream,400,new{error="size"});return;}byte[] body=new byte[length];int count=0;while(count<length){int n=stream.Read(body,count,length-count);if(n==0)throw new IOException("送信が途中で終了しました");count+=n;}lock(Gate)Save(Encoding.UTF8.GetString(body));Reply(stream,200,new{ok=true});return;
   }Reply(stream,404,new{error="route"});return;
  }
  if(request[0]!="GET"){Reply(stream,405,new{error="method"});return;}string name=path=="/"?"index.html":path.TrimStart('/');var allowed=new Dictionary<string,string>{{"index.html","text/html; charset=utf-8"},{"app.js","application/javascript; charset=utf-8"},{"sw.js","application/javascript; charset=utf-8"},{"manifest.webmanifest","application/manifest+json"},{"icon-192.png","image/png"},{"icon-512.png","image/png"}};string mime;if(!allowed.TryGetValue(name,out mime)){Reply(stream,404,new{error="file"});return;}Send(stream,200,File.ReadAllBytes(Path.Combine(Root,"dist",name)),mime);
 }catch(InvalidOperationException){try{Reply(stream,409,new{error="newer-data"});}catch{}}catch(Exception){try{Reply(stream,500,new{error="save-or-read-failed"});}catch{}}}}
}
